import { A11yModule, CdkTrapFocus, FocusKeyManager } from '@angular/cdk/a11y';
import { CdkAccordionModule } from '@angular/cdk/accordion';
import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { OverlayModule } from '@angular/cdk/overlay';
import { NgFor, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  QueryList,
  SimpleChanges,
  ViewChild,
  ViewChildren,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  ENTER,
  LEFT_ARROW,
  RIGHT_ARROW,
  SPACE,
} from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { QOverlayComponent } from '@questrade/allspark-angular-components/overlay';
import { QProgressBarComponent } from '@questrade/allspark-angular-components/progress-bar';
import {
  clear,
  lockOutline,
  moreVertical,
  thickCheck,
  unfoldMore,
} from '@questrade/allspark-icons/icons';
import { Observable, Subject, takeUntil } from 'rxjs';
import { QStaticStepComponent } from './static-step/static-step.component';
import { QStepComponent } from './step/step.component';
import { QSubStepComponent } from './sub-step/sub-step.component';
import { QStepperStaticStep } from './types/static-step.interface';
import { QStepperBeforeStepChangeEvent } from './types/step-change-event.type';
import { QStepperStep } from './types/step.interface';
import { QStepperActiveIndex } from './types/stepper-active-index.interface';
import { QStepperVariant } from './types/stepper-variant.type';
import { QStepperSubStep } from './types/sub-step.interface';

@Component({
  selector: 'q-stepper',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [
    OverlayModule,
    NgIf,
    NgFor,
    NgTemplateOutlet,
    QStepComponent,
    QStaticStepComponent,
    QIconComponent,
    QInteractiveIconComponent,
    QOverlayComponent,
    QProgressBarComponent,
    CdkAccordionModule,
    CdkTrapFocus,
    A11yModule,
  ],
  providers: [QDestroyService],
  templateUrl: './stepper.component.html',
  styleUrls: ['./stepper.component.scss'],
})
export class QStepperComponent implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @Output() readonly activeIndexChange = new EventEmitter<QStepperActiveIndex>();
  @Output() readonly overallProgressChange = new EventEmitter<number>();

  @Input() steps: QStepperStep[] = [];
  @Input() staticSteps: QStepperStaticStep[] = [];
  @Input() variant: QStepperVariant = 'standard';
  @Input({ transform: booleanAttribute }) showProgressOnActive = false;
  @Input({ transform: booleanAttribute }) showProgressOnCompleted = false;
  @Input() beforeActiveStepChange: QStepperBeforeStepChangeEvent | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-stepper';

  @Input() get activeIndex(): QStepperActiveIndex {
    return this._activeIndex;
  }
  set activeIndex(value: QStepperActiveIndex | null) {
    if (value) {
      this._activeIndex = value;
    }
  }

  @ViewChildren(QStepComponent) _stepList!: QueryList<QStepComponent>;
  @ViewChild(QOverlayComponent) _overlay!: QOverlayComponent;

  @HostBinding('class') hostClass = 'q-stepper';

  _horizontalView = false;
  _stepsViewOpen = false;
  _overallProgress = 0;
  _isMobileView = false;

  private _stepActivatedByKeyboard$ = new Subject<void>();
  private _activeIndex: QStepperActiveIndex = { stepIndex: 0, subStepIndex: 0 };
  private _keyManager: FocusKeyManager<QStepComponent | QSubStepComponent> | null = null;
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _destroy$ = inject(QDestroyService);

  ngOnInit(): void {
    this._registerIcons();
    this._breakpointObserver
      .observe(['(max-width: 599px)', '(max-width: 1019px)'])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result: BreakpointState) => {
        this._isMobileView = result.breakpoints['(max-width: 599px)'];
        this._horizontalView = result.breakpoints['(max-width: 1019px)'];
        this._updateViewPositionStrategy();
        this._calculateOverallProgress();
        this._cdr.markForCheck();
      });
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { steps, activeIndex } = changes;

    if (steps?.currentValue?.length || activeIndex?.currentValue) {
      this._calculateOverallProgress();
    }
  }

  ngAfterViewInit(): void {
    this._stepList.changes
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => this._updateFocusKeyManagerEntries());

    this._updateFocusKeyManagerEntries();
  }

  ngOnDestroy(): void {
    this._keyManager?.destroy();
  }

  get isActiveStepCompleted(): boolean {
    return this.activeStep?.subSteps?.length
      ? !!this.activeStep?.subSteps?.every((sub) => sub.completed)
      : !!this.activeStep?.completed;
  }

  get activeSubStep(): QStepperSubStep | undefined {
    return this.activeStep?.subSteps?.find((_, index) => this.activeIndex?.subStepIndex === index);
  }

  get activeStep(): QStepperStep | undefined {
    if (!this.activeIndex) return;
    return this.steps?.[this.activeIndex.stepIndex];
  }

  get stepActivatedByKeyboard(): Observable<void> {
    return this._stepActivatedByKeyboard$;
  }

  _onActiveIndexChange(activeIndex: QStepperActiveIndex): void {
    this.activeIndex = activeIndex;
    this.activeIndexChange.emit(this.activeIndex);
    this._stepsViewOpen = false;
    this._overlay?.close();
  }

  _calculateOverallProgress(): void {
    if (!this.steps.length || !this._horizontalView) return;

    let completedSteps = 0;
    let totalWeight = 0;

    this.steps.forEach((step) => {
      if (step.subSteps?.length) {
        const completedSubSteps = step.subSteps.filter((subStep) => subStep.completed).length;
        const subStepProgress = Math.floor((completedSubSteps / step.subSteps.length) * 100);
        completedSteps += subStepProgress;
      } else if (step.completed) {
        completedSteps += 100;
      }
      totalWeight += 100;
    });

    this._overallProgress = Math.floor((completedSteps / totalWeight) * 100);

    this.overallProgressChange.emit(this._overallProgress);

    /*
        This is necessary because the design spec requires a "just-started" step to have
        a small portion of the bar filled. This helps users understand that it is the active step.
        We add the value at the end, so in the next run, the added value doesn't mess with the calculation.
        */
    if (completedSteps % 100 === 0) {
      this._overallProgress += 2;
    }
  }

  _handleKeydown(event: KeyboardEvent): void {
    const activeItem = this._keyManager?.activeItem;

    if (!activeItem) {
      this._keyManager?.onKeydown(event);
      return;
    }

    let callStepActiveByKeyboard = false;

    switch (event.code) {
      case LEFT_ARROW:
      case RIGHT_ARROW:
        if (activeItem instanceof QStepComponent) {
          if (event.code === LEFT_ARROW && activeItem._stepExpanded) {
            activeItem._onStepClick();
          }

          if (event.code === RIGHT_ARROW && activeItem.showAccordion) {
            const stepElement = this._getStepElement(activeItem.index);

            if (!activeItem._stepExpanded) {
              activeItem._onStepClick();

              this._updateFocusKeyManagerEntries();
              this._cdr.detectChanges();

              if (stepElement) {
                this._keyManager?.setActiveItem(stepElement);
              }
            } else {
              const subStepElement = stepElement?._subStepList.get(0);
              if (subStepElement) {
                this._keyManager?.setActiveItem(subStepElement);
              }
            }
          }
        }

        if (activeItem instanceof QSubStepComponent && event.code === LEFT_ARROW) {
          const parentStepElement = this._getStepElement(activeItem.parentIndex);
          if (parentStepElement) {
            this._keyManager?.setActiveItem(parentStepElement);
          }
        }

        break;
      case ENTER:
      case SPACE:
        callStepActiveByKeyboard =
          activeItem instanceof QSubStepComponent ||
          (activeItem instanceof QStepComponent && !activeItem.showAccordion);

        if (callStepActiveByKeyboard) {
          this._stepActivatedByKeyboard$.next();
        }

        break;
      default:
        this._keyManager?.onKeydown(event);
    }
  }

  _onStepFocus(stepComponent: QStepComponent | QSubStepComponent): void {
    this._keyManager?.setActiveItem(stepComponent);
  }

  _toggleOverlay(): void {
    this._overlay.isOpened ? this._overlay.close() : this._overlay.open();

    if (this._overlay.isOpened) {
      this._updateViewPositionStrategy();
    }
  }

  _updateViewPositionStrategy(): void {
    if (!this._overlay) return;

    this._overlay.updateSize({
      width: this._isMobileView ? '100%' : '360px',
      height: this._isMobileView ? '100%' : 'auto',
      maxHeight: this._isMobileView ? '100%' : '550px',
    });

    this._overlay.updatePositionStrategy(this._isMobileView ? 'global' : 'connected');
  }

  _isPreviousStepCompleted(index: number): boolean {
    if (index === 0) return false;
    const previousStep = this.steps[index - 1];
    return previousStep.subSteps?.every((sub) => sub.completed) || previousStep.completed || false;
  }

  _isPreviousStaticStepCompleted(index: number): boolean {
    if (index === 0) return false;
    return this.staticSteps[index - 1].status === 'completed';
  }

  private _registerIcons(): void {
    this._iconRegistry.registerIcons([clear, thickCheck, lockOutline, moreVertical, unfoldMore]);
  }

  private _getStepElement(stepIndex: number): QStepComponent | undefined {
    return this._stepList.find((step) => step.index === stepIndex);
  }

  private _updateFocusKeyManagerEntries(): void {
    const flattenedSteps = this._stepList
      .toArray()
      .flatMap((step) =>
        step._subStepList?.length ? [step, ...step._subStepList.toArray()] : step,
      );

    this._keyManager = new FocusKeyManager(flattenedSteps).withHomeAndEnd().withTypeAhead();
  }
}
