import { NgClass, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { QProgressBarComponent } from '@questrade/allspark-angular-components/progress-bar';
import { QStepperStaticStep } from '../types/static-step.interface';

@Component({
  selector: 'q-static-step',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgIf, NgClass, NgTemplateOutlet, QProgressBarComponent],
  providers: [QDestroyService],
  templateUrl: './static-step.component.html',
  styleUrls: ['./static-step.component.scss'],
})
export class QStaticStepComponent {
  @Input({ required: true }) step!: QStepperStaticStep;
  @Input({ required: true }) index!: number;
  @Input() last = false;
  @Input() previousStepCompleted = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-static-step';

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-static-step',
      this.step?.status === 'completed' && 'q-static-step-completed',
      this.previousStepCompleted && 'q-static-step-previous-completed',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _getProgressValue(): number {
    return ['completed', 'pending'].includes(this.step.status) ? 100 : 0;
  }
}
