import { FocusableOption } from '@angular/cdk/a11y';
import { CdkAccordionItem, CdkAccordionModule } from '@angular/cdk/accordion';
import { NgFor, NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  OnChanges,
  OnInit,
  Output,
  QueryList,
  SimpleChanges,
  ViewChild,
  ViewChildren,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { isPresent } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { QProgressBarComponent } from '@questrade/allspark-angular-components/progress-bar';
import { chevronDown } from '@questrade/allspark-icons/icons';
import { of, take, takeUntil } from 'rxjs';
import { QSubStepComponent } from '../sub-step/sub-step.component';
import { QStepperBeforeStepChangeEvent } from '../types/step-change-event.type';
import { QStepperStep } from '../types/step.interface';
import { QStepperActiveIndex } from '../types/stepper-active-index.interface';

@Component({
  selector: 'q-step',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  templateUrl: './step.component.html',
  styleUrls: ['./step.component.scss'],
  imports: [
    CdkAccordionModule,
    NgIf,
    NgFor,
    QSubStepComponent,
    QProgressBarComponent,
    QIconComponent,
    QInteractiveIconComponent,
  ],
  providers: [QDestroyService],
})
export class QStepComponent extends CdkAccordionItem implements OnInit, OnChanges, FocusableOption {
  @Output() readonly activeIndexChange = new EventEmitter<QStepperActiveIndex>();
  @Output() readonly stepProgressChange = new EventEmitter<{ index: number; progress: number }>();
  @Output() readonly stepFocus = new EventEmitter<void>();
  @Output() readonly subStepFocus = new EventEmitter<QSubStepComponent>();

  @Input({ required: true }) index!: number;
  @Input({ required: true }) step!: QStepperStep;
  @Input({ required: true }) activeIndex!: QStepperActiveIndex;
  @Input() last = false;
  @Input() horizontalView = false;
  @Input() showProgressOnActive = false;
  @Input() showProgressOnCompleted = false;
  @Input() previousStepCompleted = false;
  @Input() beforeActiveStepChange: QStepperBeforeStepChangeEvent | null = null;
  @Input() @HostBinding('attr.data-qt') get dataQt(): string {
    return `q-step-${this.step?.title?.replaceAll(' ', '-').toLowerCase()}`;
  }

  @ViewChildren(QSubStepComponent) _subStepList!: QueryList<QSubStepComponent>;
  @ViewChild('stepHeader') _stepHeader!: ElementRef;

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-step',
      this.isCompleted && 'q-step-completed',
      this.previousStepCompleted && 'q-step-previous-completed',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _inReview = false;
  _stepExpanded = false;
  _progress = 0;
  _stepRelativeProgress = 0;

  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _destroy$ = inject(QDestroyService);

  override ngOnInit(): void {
    this._iconRegistry.registerIcon(chevronDown);
    this._setRelativeProgress();
    this._updateProgress();
    this._setDefaultValues();
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { activeIndex } = changes;

    if (this.isActive && !this.step?.subSteps?.some((sub) => sub.completed)) {
      this._updateProgress();
    }

    if (activeIndex) {
      this._activateStep();
      this._resetNonClicked();
      this._updateProgress();
    }
  }

  _onStepClick(): void {
    if (!this.isLocked && this._progress > 0) {
      if (this.isCompleted) {
        this._setToggleState();
      }

      if (this.showAccordion) return;

      this._changeActiveIndex();
    }
  }

  _changeActiveIndex(): void {
    if (!this.isActive) {
      const nextIndex = {
        stepIndex: this.index,
        ...(this.hasSubSteps && { subStepIndex: 0 }),
      };

      const beforeActiveStepChange$ = this.beforeActiveStepChange
        ? this.beforeActiveStepChange(this.activeIndex, nextIndex)
        : of(true);

      beforeActiveStepChange$.pipe(take(1), takeUntil(this._destroy$)).subscribe({
        next: (success: boolean) => {
          if (success) {
            this.activeIndex = nextIndex;
            this.activeIndexChange.emit(this.activeIndex);
          }
        },
      });
    }
  }

  _onActiveIndexChange(activeIndex: QStepperActiveIndex): void {
    this.activeIndex = activeIndex;
    this.activeIndexChange.emit(this.activeIndex);
  }

  _onSubStepCompleted(): void {
    this._updateProgress();
  }

  _updateProgress(): void {
    const completedSubSteps = this.step?.subSteps?.filter((sub) => sub.completed).length || 0;
    let currentProgress = 0;

    if (this.isCompleted) {
      currentProgress = 100;
    } else if (!completedSubSteps && this.isActive) {
      currentProgress = 2;
    } else {
      currentProgress = completedSubSteps * this._stepRelativeProgress;
    }

    this._progress = Math.trunc(currentProgress);

    this.stepProgressChange.emit({
      index: this.index,
      progress: this._progress,
    });
  }

  _onStepFocus(): void {
    this.stepFocus.emit();
  }

  _onSubStepFocus(subStep: QSubStepComponent): void {
    this.subStepFocus.emit(subStep);
  }

  /** @hidden */
  focus(): void {
    this._stepHeader.nativeElement.focus();
  }

  /** @hidden */
  getLabel(): string {
    return this.step?.title;
  }

  get isActive(): boolean {
    return this.index === this.activeIndex?.stepIndex;
  }

  get isLocked(): boolean {
    return !this.step?.editable && this.isCompleted;
  }

  get isCompleted(): boolean {
    return this.hasSubSteps
      ? !!this.step?.subSteps?.every((sub) => sub.completed)
      : !!this.step?.completed;
  }

  get showAccordion(): boolean {
    return (
      this.isCompleted &&
      (this.step?.editable || !isPresent(this.step?.editable)) &&
      this.hasSubSteps
    );
  }

  get hasSubSteps(): boolean {
    return !!this.step?.subSteps?.length;
  }

  get circularProgressLabel(): string {
    return String(this.index + 1);
  }

  get showProgress(): boolean {
    return (
      (this.showProgressOnActive && this._progress > 0 && !this.isCompleted) ||
      (this.showProgressOnCompleted && this.isCompleted)
    );
  }

  get ariaGroupId(): string | null {
    return this.step.subSteps?.length
      ? `${this.step.title?.toLowerCase().replace(/ /g, '-')}-idx${this.index}-subtree`
      : null;
  }

  private _setDefaultValues(): void {
    this.step = {
      ...this.step,
      editable: !isPresent(this.step?.editable) ? true : this.step?.editable,
    };
  }

  private _setToggleState(): void {
    if (this.isCompleted && !this.isLocked) {
      this._inReview = !this._inReview;
    }

    if (this.showAccordion) {
      this._stepExpanded = !this._stepExpanded;
    }
  }

  private _activateStep(): void {
    if (this.isCompleted) {
      if (!this._stepExpanded && !this._inReview) {
        this._inReview = true;

        if (this.showAccordion) {
          this._stepExpanded = true;
        }
      }
    }
  }

  private _resetNonClicked(): void {
    if (!this.isActive && this.isCompleted && (this._stepExpanded || this._inReview)) {
      this._resetToggleState();
    }
  }

  private _resetToggleState(): void {
    this._stepExpanded = false;
    this._inReview = false;
  }

  private _setRelativeProgress(): void {
    const subStepLength = this.step?.subSteps?.length;
    this._stepRelativeProgress = subStepLength ? 100 / subStepLength : 1;
  }
}
