import { FocusableOption } from '@angular/cdk/a11y';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { Subscription, of, take, takeUntil } from 'rxjs';
import { QStepperBeforeStepChangeEvent } from '../types/step-change-event.type';
import { QStepperActiveIndex } from '../types/stepper-active-index.interface';
import { QStepperSubStep } from '../types/sub-step.interface';

@Component({
  selector: 'q-sub-step',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  templateUrl: './sub-step.component.html',
  styleUrls: ['./sub-step.component.scss'],
  providers: [QDestroyService],
})
export class QSubStepComponent implements OnChanges, OnDestroy, FocusableOption {
  @Output() readonly completedChange = new EventEmitter<void>();
  @Output() readonly activeIndexChange = new EventEmitter<QStepperActiveIndex>();
  @Output() readonly subStepFocus = new EventEmitter<void>();

  @Input() beforeActiveStepChange: QStepperBeforeStepChangeEvent | null = null;
  @Input({ required: true }) parentIndex!: number;
  @Input({ required: true }) subStep!: QStepperSubStep;
  @Input({ required: true }) index!: number;
  @Input({ required: true }) activeIndex!: QStepperActiveIndex;
  @Input() parentExpanded = false;
  @Input() @HostBinding('attr.data-qt') get dataQt(): string {
    return `q-sub-step-${this.subStep.title.replaceAll(' ', '-').toLowerCase()}`;
  }

  @ViewChild('subStepContent') _subStepContent!: ElementRef;

  private beforeActiveStepChangeSub = Subscription.EMPTY;
  private readonly _destroy$ = inject(QDestroyService);

  ngOnChanges(changes: SimpleChanges): void {
    const { subStep } = changes;

    if (subStep?.currentValue?.completed) {
      this.completedChange.emit();
    }
  }

  ngOnDestroy(): void {
    this.beforeActiveStepChangeSub?.unsubscribe();
  }

  _onSubStepClick(): void {
    if (!this.isActive) {
      const nextIndex = { stepIndex: this.parentIndex, subStepIndex: this.index };

      const beforeActiveStepChange$ = this.beforeActiveStepChange
        ? this.beforeActiveStepChange(this.activeIndex, nextIndex)
        : of(true);
      beforeActiveStepChange$.pipe(take(1), takeUntil(this._destroy$)).subscribe({
        next: (success: boolean) => {
          if (success) {
            this.activeIndex = nextIndex;
            this.activeIndexChange.emit(this.activeIndex);
          }
        },
      });
    }
  }

  _onSubStepFocus(): void {
    this.subStepFocus.emit();
  }

  /** @hidden */
  focus(): void {
    this._subStepContent.nativeElement.focus();
  }

  /** @hidden */
  getLabel(): string {
    return this.subStep?.title;
  }

  get isActive(): boolean {
    return (
      this.parentIndex === this.activeIndex?.stepIndex &&
      this.index === this.activeIndex?.subStepIndex
    );
  }

  get disabled(): boolean {
    return !this.parentExpanded;
  }
}
